/* About.r - Mac-59's About box (ALRT/DITL 500), Apple menu and version ('vers' 1, Visual Architect's template said
   "MyApp 1.0d1, (c)1993 My Software Inc."). x_CApp.cp (regenerated by VA) still calls ParamText("CApp", "My Software
   Inc"): the text here uses no ^0/^1. The emulator core's origin and the trademark note are in the box, as in the
   ReadMes: the name TI-59 only describes what Mac-59 emulates.
   Rez -a into Project Resources.rsrc; MENU 1 goes into Visual Architect.rsrc, which holds VA's Apple menu. */

#include "Types.r"

data 'ALRT' (500, "About", purgeable) {
	$"0028 0028 0118 01E0 01F4 4444"		/* top 40, left 40, bottom 280, right 480, DITL 500, stages */
};

resource 'DITL' (500, "About", purgeable) {
	{
		{208, 360, 228, 428}, Button { enabled, "OK" },
		{12, 20, 30, 420}, StaticText { disabled, "Mac-59 1.1 \0xD0 der TI-59 auf dem Macintosh" },
		{38, 20, 72, 420}, StaticText { disabled, "\0xA9 2026 Pit F\0x9Arster \0xD0 geschrieben mit Claude Code via AppleBridge." },
		{78, 20, 112, 420}, StaticText { disabled, "Oberfl\0x8Ache mit Symantec Visual Architect gebaut, Code mit Symantec C++ 7 und der THINK Class Library." },
		{118, 20, 152, 420}, StaticText { disabled, "Emulator-Kern aus Calc-U-59 von Martin Erzberger (GPL-3.0)." },
		{158, 20, 200, 420}, StaticText { disabled, "TI-59 und Texas Instruments sind Marken von Texas Instruments Incorporated. Mac-59 steht in keiner Verbindung zu TI." }
	}
};

resource 'MENU' (1, "Apple", preload) {
	1,
	textMenuProc,
	0x7FFFFFFD,
	enabled,
	apple,
	{
		"\0x86ber Mac-59\0xC9#256", noIcon, noKey, noMark, plain,
		"-", noIcon, noKey, noMark, plain
	}
};

resource 'vers' (1) {
	0x01, 0x10, release, 0x00, verGermany,
	"1.1",
	"1.1, \0xA9 2026 Pit F\0x9Arster \0xD0 Mac-59, der TI-59 auf dem Macintosh"
};
